<?php
namespace App\Services;
use App\Models\{AttributionTouch,AuditLog,JpHold,RewardTransaction,Unlock,UnlockParticipation,UnlockStatusHistory,User};
use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class UnlockParticipationService {
 public function interest(Unlock $u,User $user):UnlockParticipation{return DB::transaction(function()use($u,$user){$p=UnlockParticipation::firstOrNew(['unlock_id'=>$u->id,'user_id'=>$user->id]);if(!UnlockParticipation::terminal($p->status??'')){$p->status=UnlockParticipation::INTERESTED;$p->interested_at??=now();$p->save();}return $p;});}
 public function commit(Unlock $unlock,User $user):UnlockParticipation{return DB::transaction(function()use($unlock,$user){$user=User::lockForUpdate()->findOrFail($user->id);$u=Unlock::lockForUpdate()->findOrFail($unlock->id);if($u->status!==Unlock::ACTIVE||($u->commitment_deadline&&$u->commitment_deadline->isPast()))throw ValidationException::withMessages(['unlock'=>'Este desbloqueo no acepta compromisos.']);if($u->jp_deposit>0&&!config('unlocks.jp_commitments_enabled'))throw ValidationException::withMessages(['unlock'=>'Los compromisos con JP aún no están activos.']);$member=$user->hasActiveMembership();if((!$member&&!$u->free_user_eligible)||($member&&!$u->member_eligible))throw ValidationException::withMessages(['unlock'=>'No eres elegible para este desbloqueo.']);$p=UnlockParticipation::where(['unlock_id'=>$u->id,'user_id'=>$user->id])->lockForUpdate()->first();if($p?->status===UnlockParticipation::COMMITTED)return $p;if($p&&UnlockParticipation::terminal($p->status))throw ValidationException::withMessages(['unlock'=>'Esta participación ya terminó.']);if($u->maximum_capacity!==null&&$u->committedCount()>=$u->maximum_capacity)throw ValidationException::withMessages(['unlock'=>'Este desbloqueo está completo.']);if($u->jp_deposit>0&&app(JpBalanceService::class)->for($user)['spendable']<$u->jp_deposit)throw ValidationException::withMessages(['jp'=>'No tienes JP suficientes para la garantía.']);$p??=new UnlockParticipation(['unlock_id'=>$u->id,'user_id'=>$user->id]);$touch=AttributionTouch::where('unlock_id',$u->id)->where('user_id',$user->id)->whereNotNull('referrer_user_id')->where('referrer_user_id','!=',$user->id)->latest('occurred_at')->first();$p->fill(['status'=>UnlockParticipation::COMMITTED,'committed_at'=>now(),'referral_attribution_touch_id'=>$p->referral_attribution_touch_id??$touch?->id]);$p->save();if($touch)app(AnalyticsTracker::class)->unlock($u,'unlock_referral_committed');if($u->jp_deposit>0){$h=JpHold::firstOrCreate(['unlock_participation_id'=>$p->id],['user_id'=>$user->id,'amount'=>$u->jp_deposit,'status'=>JpHold::HELD,'reason'=>'unlock_commitment','held_at'=>now()]);$this->audit($user->id,'unlock_jp_held',$h,['unlock_id'=>$u->id,'amount'=>$h->amount]);app(AnalyticsTracker::class)->unlock($u,'unlock_jp_held');}if($u->committedCount()>=$u->minimum_commitments)$this->openConfirmation($u);return $p->refresh();});}
 public function openConfirmation(Unlock $unlock):void{$u=Unlock::lockForUpdate()->findOrFail($unlock->id);if($u->status!==Unlock::ACTIVE)return;$u->update(['status'=>Unlock::UNLOCKED,'goal_reached_at'=>$u->goal_reached_at??now(),'status_changed_at'=>now()]);UnlockStatusHistory::create(['unlock_id'=>$u->id,'from_status'=>Unlock::ACTIVE,'to_status'=>Unlock::GOAL_REACHED,'reason'=>'Minimum commitments reached']);UnlockStatusHistory::create(['unlock_id'=>$u->id,'from_status'=>Unlock::GOAL_REACHED,'to_status'=>Unlock::UNLOCKED,'reason'=>'Result available']);UnlockParticipation::where('unlock_id',$u->id)->where('status',UnlockParticipation::COMMITTED)->update(['status'=>UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION,'confirmation_requested_at'=>now(),'updated_at'=>now()]);}
 public function confirm(Unlock $unlock,User $user):UnlockParticipation{return DB::transaction(function()use($unlock,$user){$u=Unlock::lockForUpdate()->findOrFail($unlock->id);$p=$this->participant($u,$user);if($p->status===UnlockParticipation::CONFIRMED)return $p;if($u->status!==Unlock::UNLOCKED||($u->confirmation_deadline&&$u->confirmation_deadline->isPast())||$p->status!==UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION)throw ValidationException::withMessages(['unlock'=>'La confirmación no está disponible.']);$p->update(['status'=>UnlockParticipation::CONFIRMED,'confirmed_at'=>now()]);return $p;});}
 public function cancel(Unlock $unlock,User $user):UnlockParticipation{return DB::transaction(function()use($unlock,$user){$u=Unlock::lockForUpdate()->findOrFail($unlock->id);$p=$this->participant($u,$user);if(!in_array($p->status,[UnlockParticipation::COMMITTED,UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION,UnlockParticipation::CONFIRMED],true)||($u->cancellation_deadline&&$u->cancellation_deadline->isPast()))throw ValidationException::withMessages(['unlock'=>'No puedes cancelar esta participación.']);$p->update(['status'=>UnlockParticipation::CANCELLED_ON_TIME,'cancelled_at'=>now()]);$this->release($p,$user->id,'user_cancellation');return $p;});}
 public function fulfill(UnlockParticipation $participation,User $actor,string $source='manual',?string $note=null,?int $redemptionId=null,bool $override=false):UnlockParticipation{return DB::transaction(function()use($participation,$actor,$source,$note,$redemptionId,$override){$p=UnlockParticipation::lockForUpdate()->findOrFail($participation->id);$u=Unlock::lockForUpdate()->findOrFail($p->unlock_id);if($p->status===UnlockParticipation::FULFILLED)return $p;if($p->status!==UnlockParticipation::CONFIRMED||$u->status===Unlock::CANCELLED)throw ValidationException::withMessages(['unlock'=>'La participación no se puede validar.']);if(!$override&&(($u->fulfillment_starts_at&&$u->fulfillment_starts_at->isFuture())||($u->fulfillment_ends_at&&$u->fulfillment_ends_at->isPast())))throw ValidationException::withMessages(['unlock'=>'Fuera de la ventana de cumplimiento.']);$p->update(['status'=>UnlockParticipation::FULFILLED,'fulfilled_at'=>now(),'fulfilled_by_user_id'=>$actor->id,'fulfillment_source'=>$source,'fulfillment_note'=>$note,'fulfillment_redemption_id'=>$redemptionId]);$this->release($p,$actor->id,'fulfillment');$this->bonus($p,$u,$actor->id);$this->audit($actor->id,'unlock_fulfilled',$p,['unlock_id'=>$u->id,'source'=>$source]);app(AnalyticsTracker::class)->unlock($u,'unlock_fulfilled');if($p->referral_attribution_touch_id)app(AnalyticsTracker::class)->unlock($u,'unlock_referral_fulfilled');return $p;});}
 public function fulfillForRedemption(int $id,int $user,int $benefit):void{UnlockParticipation::where('user_id',$user)->where('status',UnlockParticipation::CONFIRMED)->whereHas('unlock',fn($q)=>$q->where('linked_benefit_id',$benefit)->where('status',Unlock::UNLOCKED))->get()->each(fn($p)=>$this->fulfill($p,User::findOrFail($user),'benefit_redemption',null,$id));}
 public function processDeadlines():array{$expired=0;$noShows=0;Unlock::where('status',Unlock::UNLOCKED)->chunkById(100,function($us)use(&$expired,&$noShows){foreach($us as $u){if($u->confirmation_deadline&&$u->confirmation_deadline->isPast())UnlockParticipation::where('unlock_id',$u->id)->where('status',UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION)->get()->each(function($p)use(&$expired){DB::transaction(function()use($p,&$expired){$p=UnlockParticipation::lockForUpdate()->find($p->id);if($p->status===UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION){$p->update(['status'=>UnlockParticipation::EXPIRED,'expired_at'=>now()]);$this->release($p,0,'confirmation_expired');$expired++;}});});if($u->fulfillment_ends_at&&$u->fulfillment_ends_at->isPast())UnlockParticipation::where('unlock_id',$u->id)->where('status',UnlockParticipation::CONFIRMED)->get()->each(function($p)use(&$noShows){DB::transaction(function()use($p,&$noShows){$p=UnlockParticipation::lockForUpdate()->find($p->id);if($p->status===UnlockParticipation::CONFIRMED){$p->update(['status'=>UnlockParticipation::NO_SHOW,'no_show_at'=>now()]);$this->forfeit($p,0);$noShows++;}});});}});return compact('expired','noShows');}
 public function releaseForUnlock(Unlock $u,string $reason):void{UnlockParticipation::where('unlock_id',$u->id)->get()->each(fn($p)=>$this->release($p,0,$reason));}
 public function remove(UnlockParticipation $participation,User $actor,string $reason):UnlockParticipation{return DB::transaction(function()use($participation,$actor,$reason){$p=UnlockParticipation::lockForUpdate()->findOrFail($participation->id);if($p->status===UnlockParticipation::REMOVED)return $p;if(UnlockParticipation::terminal($p->status))throw ValidationException::withMessages(['participation'=>'No se puede retirar una participación terminada.']);$before=$p->status;$p->update(['status'=>UnlockParticipation::REMOVED]);$this->release($p,$actor->id,'admin_remove');$this->audit($actor->id,'unlock_participation_removed',$p,['unlock_id'=>$p->unlock_id,'before'=>$before,'after'=>UnlockParticipation::REMOVED,'reason'=>$reason]);return $p;});}
 public function exceptionalRelease(UnlockParticipation $participation,User $actor,string $reason):UnlockParticipation{return DB::transaction(function()use($participation,$actor,$reason){$p=UnlockParticipation::lockForUpdate()->findOrFail($participation->id);$hold=JpHold::where('unlock_participation_id',$p->id)->lockForUpdate()->first();if(!$hold||$hold->status!==JpHold::HELD)throw ValidationException::withMessages(['jp'=>'No existe una garantía JP activa para liberar.']);$before=$p->status;$p->update(['status'=>UnlockParticipation::REMOVED]);$this->release($p,$actor->id,'admin_exceptional_release');$this->audit($actor->id,'unlock_jp_exceptionally_released',$p,['unlock_id'=>$p->unlock_id,'before'=>$before,'after'=>UnlockParticipation::REMOVED,'reason'=>$reason]);return $p;});}
 public function correct(UnlockParticipation $participation,User $actor,string $correction,string $reason):UnlockParticipation{return DB::transaction(function()use($participation,$actor,$correction,$reason){$p=UnlockParticipation::lockForUpdate()->findOrFail($participation->id);if($correction!=='confirm_to_cancelled_on_time'||$p->status!==UnlockParticipation::CONFIRMED)throw ValidationException::withMessages(['correction'=>'La corrección solicitada no es segura.']);$p->update(['status'=>UnlockParticipation::CANCELLED_ON_TIME,'cancelled_at'=>now()]);$this->release($p,$actor->id,'admin_state_correction');$this->audit($actor->id,'unlock_participation_corrected',$p,['unlock_id'=>$p->unlock_id,'before'=>UnlockParticipation::CONFIRMED,'after'=>UnlockParticipation::CANCELLED_ON_TIME,'correction'=>$correction,'reason'=>$reason]);return $p;});}
 private function participant(Unlock $u,User $user):UnlockParticipation{return UnlockParticipation::where(['unlock_id'=>$u->id,'user_id'=>$user->id])->lockForUpdate()->firstOrFail();} private function release(UnlockParticipation $p,int $actor,string $reason):void{$h=JpHold::where('unlock_participation_id',$p->id)->lockForUpdate()->first();if(!$h||$h->status!==JpHold::HELD)return;$h->update(['status'=>JpHold::RELEASED,'released_at'=>now()]);$this->audit($actor,'unlock_jp_released',$h,['unlock_id'=>$p->unlock_id,'amount'=>$h->amount,'reason'=>$reason]);}private function forfeit(UnlockParticipation $p,int $actor):void{$h=JpHold::where('unlock_participation_id',$p->id)->lockForUpdate()->first();if(!$h||$h->status!==JpHold::HELD)return;$h->update(['status'=>JpHold::FORFEITED,'forfeited_at'=>now()]);$this->audit($actor,'unlock_jp_forfeited',$h,['unlock_id'=>$p->unlock_id,'amount'=>$h->amount]);}private function bonus(UnlockParticipation $p,Unlock $u,int $actor):void{if(!$u->jp_completion_bonus)return;$r=RewardTransaction::firstOrCreate(['unlock_participation_id'=>$p->id],['beneficiary_user_id'=>$p->user_id,'beneficiary_type'=>'USER','beneficiary_id'=>$p->user_id,'reward_type'=>'JP','amount'=>$u->jp_completion_bonus,'status'=>RewardTransaction::STATUS_AVAILABLE,'available_at'=>now(),'source'=>'unlock_fulfillment']);if($r->wasRecentlyCreated)$this->audit($actor,'unlock_jp_bonus_awarded',$r,['unlock_id'=>$u->id,'amount'=>$u->jp_completion_bonus]);}private function audit(int $actor,string $action,$subject,array $metadata):void{AuditLog::create(['actor_user_id'=>$actor?:null,'action'=>$action,'subject_type'=>$subject::class,'subject_id'=>$subject->id,'metadata'=>$metadata]);}}
